def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]

    projections = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: c - r,
        lambda r, c: c + r,
    ]

    choices = []
    for mode, project in enumerate(projections):
        for period in range(1, max(h, w) + 1):
            pattern = {}
            valid = True
            for r, c, color in cells:
                residue = project(r, c) % period
                if residue in pattern and pattern[residue] != color:
                    valid = False
                    break
                pattern[residue] = color
            if valid and len(pattern) == period:
                choices.append((period, mode, pattern, project))
                break

    if not choices:
        return [row[:] for row in grid]

    _, _, pattern, project = min(choices, key=lambda x: (x[0], x[1]))
    return [[pattern[project(r, c) % len(pattern)] for c in range(w)] for r in range(h)]
